package com.gregtech.gregtech.registry;
import com.gregtech.gregtech.block.misc.*;import com.gregtech.gregtech.content.logistics.ExtenderSpec;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockBehaviour;import net.minecraft.world.level.material.MapColor;import net.neoforged.neoforge.registries.DeferredHolder;
public final class GTRelaysFilters {private GTRelaysFilters(){}public static final java.util.List<DeferredHolder<Block,? extends Block>> EXTENDERS=new java.util.ArrayList<>();public static final java.util.List<DeferredHolder<Block,AutoHammerBlock>> HAMMERS=new java.util.ArrayList<>();public static final java.util.List<DeferredHolder<Block,AutoIgniterBlock>> IGNITERS=new java.util.ArrayList<>();public static final java.util.List<DeferredHolder<Block,FilterBlock>> FILTERS=new java.util.ArrayList<>();
 private static BlockBehaviour.Properties props(float hardness){return BlockBehaviour.Properties.of().mapColor(MapColor.METAL).strength(hardness,hardness).requiresCorrectToolForDrops();}
 public static void initialize(){for(var spec:com.gregtech.gregtech.content.tool.AutomaticToolRules.ALL){if(spec.igniter()!=true)continue;var b=GTBlocks.BLOCKS.register(spec.id(),()->new AutoIgniterBlock(props(spec.hardness()),spec.input(),spec.quality()));IGNITERS.add(b);GTBlocks.BLOCK_ITEMS.register(spec.id(),()->new net.minecraft.world.item.BlockItem(b.get(),new net.minecraft.world.item.Item.Properties()));}for(var spec:com.gregtech.gregtech.content.tool.AutomaticToolRules.ALL){if(spec.igniter()!=false)continue;var b=GTBlocks.BLOCKS.register(spec.id(),()->new AutoHammerBlock(props(spec.hardness()),spec.input(),spec.quality()));HAMMERS.add(b);GTBlocks.BLOCK_ITEMS.register(spec.id(),()->new net.minecraft.world.item.BlockItem(b.get(),new net.minecraft.world.item.Item.Properties()));}String[] legacy={"basic","advanced","elite","wireless"};for(int i=0;i<legacy.length;i++){String id="extender_"+legacy[i];float hard=4+i*2;var b=GTBlocks.BLOCKS.register(id,()->new ExtenderBlock(props(hard)));EXTENDERS.add(b);GTBlocks.BLOCK_ITEMS.register(id,()->new net.minecraft.world.item.BlockItem(b.get(),new net.minecraft.world.item.Item.Properties()));}for(var spec:ExtenderSpec.values()){var b=GTBlocks.BLOCKS.register(spec.id,()->new SourceExtenderBlock(spec,props(6)));EXTENDERS.add(b);GTBlocks.BLOCK_ITEMS.register(spec.id,()->new net.minecraft.world.item.BlockItem(b.get(),new net.minecraft.world.item.Item.Properties().stacksTo(16)));}for(String kind:new String[]{"items","fluids","items_fluids","oredict"}){String id="filter_"+kind;var b=GTBlocks.BLOCKS.register(id,()->new FilterBlock(kind,props(6)));FILTERS.add(b);GTBlocks.BLOCK_ITEMS.register(id,()->new net.minecraft.world.item.BlockItem(b.get(),new net.minecraft.world.item.Item.Properties().stacksTo(16)));}}
}
